        Cooldown storage cooldown = cooldowns[msg.sender];
        uint256 assets = cooldown.underlyingAmount;

        if (block.timestamp >= cooldown.cooldownEnd || cooldownDuration == 0) {
            cooldown.cooldownEnd = 0;
            cooldown.underlyingAmount = 0;

